/** Pure roster model over data/roster.json (generated by tools/sync.py from veil-break/characters). No DOM. */

export const SLOTS = ['basic', 'active', 'signature', 'passive'];
export const KITS = {
  authored: { label: 'authored kit', detail: 'tuned from the attribute specification' },
  hypothesis: { label: 'hypothesis kit', detail: 'authored from the concept sheet; a reviewable hypothesis, tuned later' },
};
export const CLASS_COPY = {
  breaker: 'cracks barriers, crushes cover and punishes anything that stands still too long.',
  striker: 'precision damage from range — lines, fans and finishers that delete a target.',
  bastion: 'holds the street: wards, walls and bodies between the squad and the breach.',
  operator: 'tempo, healing and control — the hands that keep a run alive.',
};
const TICKS_PER_SECOND = 30;
const CENTIMETRES_PER_METRE = 100;

/** Site-relative producer paths only: never a scheme, an absolute path or a parent step. */
export function assetUrl(root, path) {
  if (typeof path !== 'string' || !path || path.startsWith('/') || path.includes('\\') || path.includes(':') || path.split('/').includes('..')) return '';
  return root + path;
}

export async function loadRoster(root, fetcher = fetch) {
  const response = await fetcher(`${root}data/roster.json`);
  if (!response.ok) throw new Error(`roster ${response.status}`);
  return response.json();
}

export function searchText(fighter) {
  return [fighter.id, fighter.name, fighter.code, fighter.callsign, fighter.role, fighter.rarity, fighter.identity, fighter.weapon, ...fighter.skills.map((s) => s.name)]
    .filter(Boolean).join(' ').toLowerCase();
}

export function matches(fighter, { query = '', role = 'all', kit = 'all' } = {}) {
  const needle = query.trim().toLowerCase();
  return (!needle || searchText(fighter).includes(needle)) && (role === 'all' || fighter.role === role) && (kit === 'all' || fighter.kit === kit);
}

export function filterFighters(fighters, filters) {
  return fighters.filter((fighter) => matches(fighter, filters));
}

export function countBy(fighters, key) {
  return fighters.reduce((counts, fighter) => ({ ...counts, [fighter[key]]: (counts[fighter[key]] || 0) + 1 }), {});
}

/** Stat bars share one scale: each stat against the roster's own maximum. */
export function statScale(fighters) {
  const keys = ['hp', 'armor', 'stability', 'moveSpeed'];
  return Object.fromEntries(keys.map((key) => [key, Math.max(...fighters.map((f) => f.stats[key]))]));
}

/** Skill readout in player units: power cost, seconds from 30 Hz ticks, metres from centimetres. */
export function skillMeta(skill) {
  if (!skill || skill.cost === undefined) return '';
  const parts = [skill.cost ? `${skill.cost} power` : 'free'];
  if (skill.cooldown) parts.push(`${(skill.cooldown / TICKS_PER_SECOND).toFixed(1)} s cooldown`);
  if (skill.windup) parts.push(`${(skill.windup / TICKS_PER_SECOND).toFixed(2)} s windup`);
  if (skill.range) parts.push(`${(skill.range / CENTIMETRES_PER_METRE).toFixed(1)} m range`);
  return parts.join(' · ');
}

/** A small seeded generator so a page can shuffle the same way twice (tests) or differently per visit. */
export function seeded(seed) {
  let state = (seed >>> 0) || 1;
  return () => {
    state ^= state << 13; state ^= state >>> 17; state ^= state << 5;
    return (state >>> 0) / 4294967296;
  };
}

/** Fisher–Yates over a copy. */
export function shuffle(items, random) {
  const pool = [...items];
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool;
}

/** One fighter from each of `count` different classes. */
export function pickSquad(fighters, random, count = 3) {
  const squad = [];
  for (const fighter of shuffle(fighters, random)) {
    if (squad.length === count) break;
    if (!squad.some((member) => member.role === fighter.role)) squad.push(fighter);
  }
  return squad;
}

/** Index arithmetic for the spotlight carousel. */
export function step(index, delta, length) {
  return ((index + delta) % length + length) % length;
}
